<style>
.fv-entry{--fv-accent:#3378f6;--fv-teal:#079b89;--fv-card:var(--surface,#fff);--fv-soft:var(--surface-2,#f5f8fc);--fv-ink:var(--text,#15243b);--fv-muted:var(--muted,#60738a);--fv-border:var(--border,#e0e7ef);max-width:1140px;margin:auto;padding:24px 24px 30px;color:var(--fv-ink)}
.fv-entry *{box-sizing:border-box;min-width:0}.fv-entry a,.fv-entry button,.fv-entry input,.fv-entry select,.fv-entry textarea,.fv-entry summary{touch-action:manipulation}
.entry-hero{display:flex;align-items:center;gap:18px;background:linear-gradient(115deg,#075f72 0%,#164798 65%,#2549a0 100%);color:#fff;border-radius:24px;padding:26px 28px;margin-bottom:22px;box-shadow:0 12px 32px #174d9515}
.entry-hero-icon{flex:0 0 56px;height:56px;border-radius:18px;display:grid;place-items:center;background:#ffffff15;border:1px solid #ffffff30;font-size:28px}
.entry-hero-copy{flex:1}.entry-eyebrow{font-size:11px;color:#d5eaf4;display:block;margin-bottom:7px}.entry-hero h1{color:#fff;font-size:23px;line-height:1.6;font-weight:750;margin:0 0 5px}.entry-hero p{font-size:12px;line-height:1.9;margin:0;color:#e1ecfa}
.entry-agent{display:flex;align-items:center;gap:10px;border-right:1px solid #ffffff35;padding-right:20px;font-size:11px;line-height:1.8;color:#d8e8fa}.entry-agent>i{font-size:22px}.entry-agent strong{display:block;font-size:13px;color:#fff;overflow-wrap:anywhere}
.entry-grid{display:grid;grid-template-columns:minmax(0,1.12fr) minmax(320px,.88fr);grid-template-areas:"info location" "buying location" "more location" "footer footer";gap:18px;align-items:start}
.entry-info{grid-area:info}.entry-location{grid-area:location;position:sticky;top:90px}.entry-buying{grid-area:buying}.entry-more{grid-area:more}
.entry-card{background:var(--fv-card);border:1px solid var(--fv-border);border-radius:20px;padding:22px;box-shadow:0 4px 20px #0f234505}
.entry-section-head{display:flex;align-items:center;gap:11px;margin-bottom:22px}.entry-section-head>div{flex:1}.entry-section-head h2{font-size:15px;font-weight:750;margin:0 0 5px;line-height:1.6}.entry-section-head p{font-size:11px;color:var(--fv-muted);margin:0;line-height:1.8}
.entry-section-icon{flex:0 0 39px;height:39px;display:grid;place-items:center;font-size:18px;border-radius:13px;color:var(--fv-accent);background:color-mix(in srgb,var(--fv-accent) 11%,var(--fv-card))}.entry-section-icon-teal{color:var(--fv-teal);background:color-mix(in srgb,var(--fv-teal) 11%,var(--fv-card))}
.entry-badge{border-radius:20px;background:var(--fv-soft);color:var(--fv-muted);padding:5px 9px;white-space:nowrap;font-size:10px}.entry-location.is-located .entry-badge{background:color-mix(in srgb,var(--fv-teal) 13%,var(--fv-card));color:var(--fv-teal)}
.fv-entry .form-label{font-size:12px;font-weight:650;margin-bottom:8px;line-height:1.8}.fv-entry .form-label small{color:var(--fv-muted);font-size:10px;font-weight:400;margin-right:4px}.entry-required{color:var(--fv-accent)}
.fv-entry .form-control,.fv-entry .form-select{min-height:48px;border-radius:12px;font-size:13px;border-color:var(--fv-border);background-color:var(--fv-soft);color:var(--fv-ink);padding-top:12px;padding-bottom:12px;transition:border-color .15s,box-shadow .15s}.fv-entry .form-control::placeholder{color:var(--fv-muted);opacity:.75}
.fv-entry .form-control:focus,.fv-entry .form-select:focus{border-color:var(--fv-accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--fv-accent) 16%,transparent);background-color:var(--fv-card)}
.fv-entry .form-control.is-invalid,.fv-entry .form-select.is-invalid{border-color:#e25b68}.fv-entry textarea{resize:vertical}.fv-entry .invalid-feedback,.fv-entry .text-danger{font-size:11px;line-height:1.9}.fv-entry .text-muted{color:var(--fv-muted)!important}
.entry-gps{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;min-height:48px;border-radius:12px;border:1px solid color-mix(in srgb,var(--fv-teal) 35%,var(--fv-border));background:color-mix(in srgb,var(--fv-teal) 9%,var(--fv-card));color:var(--fv-teal);font-size:12px;font-weight:700;transition:background .15s,transform .15s}.entry-gps:hover{background:color-mix(in srgb,var(--fv-teal) 17%,var(--fv-card))}.entry-gps i{font-size:19px}.entry-gps:disabled{opacity:.6}
.entry-status{font-size:11px;line-height:1.9;color:var(--fv-muted);margin:10px 0 13px;overflow-wrap:anywhere}#quick-map{height:278px;isolation:isolate;z-index:1;border:1px solid var(--fv-border);border-radius:15px;overflow:hidden;background:var(--fv-soft)}
.entry-address{padding-top:3px}.entry-address .entry-status{margin-bottom:4px}.entry-text-button{border:0;padding:5px 0;background:transparent;color:var(--fv-accent);font-size:11px;min-height:32px;display:inline-flex;align-items:center;gap:7px}
.entry-address-details{border-top:1px solid var(--fv-border);margin-top:10px;padding-top:12px}.entry-address-details summary{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px;font-weight:600;min-height:30px;color:var(--fv-ink)}.entry-address-details summary i{font-size:10px;color:var(--fv-muted);transition:transform .15s}.entry-address-details[open]>summary i{transform:rotate(180deg)}
.entry-attribution{font-size:9px;line-height:1.8;color:var(--fv-muted);margin:14px 0 0}.entry-attribution a{color:inherit;text-underline-offset:3px}.entry-location-error{font-size:12px;line-height:1.8;color:#dc5268;margin:10px 0 0}
.entry-disclosure{padding:0;overflow:visible}.entry-disclosure>summary{padding:19px 22px;display:flex;align-items:center;gap:11px;cursor:pointer;min-height:82px}.entry-disclosure>summary:hover .entry-summary-copy strong{color:var(--fv-accent)}
.fv-entry summary{list-style:none;cursor:pointer}.fv-entry summary::-webkit-details-marker{display:none}.entry-summary-copy{flex:1;display:flex;flex-direction:column;gap:5px}.entry-summary-copy strong{font-size:14px;line-height:1.6}.entry-summary-copy small{font-size:10px;line-height:1.7;color:var(--fv-muted)}.entry-optional{font-size:10px;white-space:nowrap;color:var(--fv-muted);padding:4px 8px;background:var(--fv-soft);border-radius:20px}
.entry-chevron{font-size:11px;color:var(--fv-muted);transition:transform .2s}.entry-disclosure[open]>summary .entry-chevron{transform:rotate(180deg)}.entry-disclosure-body{padding:20px 22px 22px;border-top:1px solid var(--fv-border)}
.fv-entry fieldset{min-width:0}.fv-entry legend{float:none;width:auto;font-size:12px;font-weight:650;margin-bottom:12px;line-height:1.8}.fv-entry .qv-choices{display:flex;flex-wrap:wrap;gap:8px;width:100%;min-width:0}.fv-entry .qv-choices label{display:inline-flex;align-items:center;gap:7px;max-width:100%;min-height:42px;border:1px solid var(--fv-border);border-radius:11px;padding:9px 12px;cursor:pointer;font-size:12px;color:var(--fv-muted);background:var(--fv-card);transition:background .15s,border-color .15s,color .15s}
.fv-entry .qv-choices input{width:15px;height:15px;flex:0 0 15px;accent-color:var(--fv-accent);margin:0;cursor:pointer}.fv-entry .qv-choices label:has(input:checked){border-color:var(--fv-accent);background:color-mix(in srgb,var(--fv-accent) 11%,var(--fv-card));color:var(--fv-accent);box-shadow:0 0 0 1px var(--fv-accent)}.fv-entry .qv-choices label:focus-within{outline:2px solid var(--fv-accent);outline-offset:3px}
.fv-entry .visit-help{padding:16px;border-radius:14px;background:var(--fv-soft);margin-bottom:0!important}.fv-entry .visit-help h3{font-size:12px;font-weight:700;margin-bottom:15px}.fv-entry small.text-muted{font-size:10px;line-height:1.9;display:inline-block}
.entry-submit-bar{grid-area:footer;position:sticky;bottom:12px;z-index:20;display:flex;align-items:center;gap:20px;border:1px solid var(--fv-border);border-radius:18px;background:var(--fv-card);padding:14px 18px;box-shadow:0 6px 26px #12284b12}
.entry-progress{display:flex;flex-wrap:wrap;gap:14px;flex:1}.entry-progress span{display:inline-flex;align-items:center;gap:6px;color:var(--fv-muted);font-size:11px}.entry-progress i{font-size:14px}.entry-progress .is-done{color:var(--fv-teal)}
.entry-submit{display:inline-flex;align-items:center;justify-content:center;gap:18px;min-height:48px;min-width:175px;padding:12px 24px;border:0;border-radius:12px;background:linear-gradient(110deg,#245fe4,#397fff);color:#fff;font-weight:700;font-size:13px;box-shadow:0 5px 14px #2667ed25;transition:filter .15s,transform .15s}.entry-submit::after{content:'←';font-size:20px;line-height:1}.entry-submit:hover{filter:brightness(1.08);transform:translateY(-1px)}.entry-submit:disabled{opacity:.65;transform:none}.entry-full-form{font-size:10px;color:var(--fv-muted);text-decoration:none;white-space:nowrap}.entry-full-form:hover{color:var(--fv-accent)}.entry-full-form-mobile{display:none}.entry-full-form-mobile a{font-size:12px;color:var(--fv-accent)}
.fv-entry :is(button,a,summary):focus-visible{outline:3px solid var(--fv-accent);outline-offset:4px}.fv-entry [hidden]{display:none!important}.fv-entry :is(input,select,textarea,details,section){scroll-margin-top:125px;scroll-margin-bottom:110px}
[data-bs-theme=dark] .fv-entry{--fv-teal:#41d1ba;--fv-accent:#80aaff}[data-bs-theme=dark] .entry-hero{background:linear-gradient(115deg,#0d5863,#17366d 70%,#1a397d);border:1px solid #82bbff25}[data-bs-theme=dark] .entry-card{box-shadow:0 8px 25px #0000000d}[data-bs-theme=dark] .entry-submit-bar{box-shadow:0 -6px 28px #00000024}
@media(min-width:1400px){.entry-grid{gap:22px}.entry-card{padding:26px}.entry-disclosure{padding:0}}
@media(max-width:991px){.fv-entry{max-width:760px;padding:20px 20px 28px}.entry-grid{grid-template-columns:minmax(0,1fr);grid-template-areas:"info" "location" "buying" "more" "footer";gap:16px}.entry-location{position:static}.entry-hero{padding:22px;gap:14px}.entry-agent{display:none}#quick-map{height:280px}.entry-submit-bar{gap:12px}.entry-full-form{display:none}.entry-full-form-mobile{display:block}}
@media(max-width:575px){.fv-entry{padding:14px 12px 20px}.entry-hero{border-radius:19px;padding:19px 17px;gap:12px;margin-bottom:16px}.entry-hero-icon{flex-basis:42px;height:46px;border-radius:14px;font-size:23px}.entry-hero h1{color:#fff;font-size:18px}.entry-hero p{font-size:11px;line-height:1.9}.entry-eyebrow{font-size:10px;margin-bottom:4px}.entry-card{padding:18px 16px;border-radius:17px}.entry-section-head{gap:10px;margin-bottom:19px}.entry-section-icon{flex-basis:34px;height:36px;border-radius:11px;font-size:17px}.entry-section-head h2{font-size:14px}.entry-section-head p{font-size:10px}.entry-badge{font-size:9px;padding:5px 7px}.fv-entry .form-control,.fv-entry .form-select{font-size:16px;min-height:48px}.fv-entry .form-label{font-size:12px}.entry-disclosure{padding:0}.entry-disclosure>summary{padding:16px;gap:9px}.entry-summary-copy strong{font-size:13px}.entry-summary-copy small{font-size:10px}.entry-disclosure-body{padding:17px 16px}.entry-optional{display:none}.entry-submit-bar{bottom:0;gap:10px;border-radius:16px 16px 0 0;padding:12px 12px calc(12px + env(safe-area-inset-bottom));margin-top:0}.entry-progress{flex-direction:column;gap:5px}.entry-progress span{font-size:10px;white-space:nowrap}.entry-progress i{font-size:12px}.entry-submit{min-width:145px;min-height:48px;padding:12px 16px;font-size:13px}#quick-map{height:235px}.entry-attribution{font-size:9px}}
@media(max-width:360px){.entry-hero-icon{display:none}.entry-hero h1{color:#fff;font-size:17px}.entry-submit{min-width:130px}.entry-section-head p{font-size:9px}.entry-badge{font-size:8px}.entry-submit-bar{gap:8px}}
@media(max-height:500px) and (max-width:991px){.entry-submit-bar{position:static}}
@media(prefers-reduced-motion:reduce){.fv-entry *{scroll-behavior:auto!important;transition:none!important}}
</style>

